/* ===== V115: كل مادة بخانة لحالها — تنقص من الصلصة ومن التمن ===== */
function supUse(cnt,sign,rice){ const S=supAll();
  const add=(n,u)=>{ if(!u||!S[n]) return; S[n].used=Math.max(0,Math.round(((S[n].used||0)+sign*u)*10)/10) };
  ['red','black'].forEach(k=>{ const c=cnt[k]||0; if(c) (settings.sauces[k].items||[]).forEach(it=>add(it.name,(+it.use||0)*c)) });
  if(rice) Object.keys(S).forEach(n=>add(n,(+S[n].perRice||0)*rice));
}
function supRender(){
  const S=supAll();
  document.querySelectorAll('[data-sup]').forEach(card=>{
    const n=card.dataset.sup, e=S[n]; if(!e) return;
    const left=Math.max(0,(e.g||0)-(e.used||0)), neg=(e.g||0)<(e.used||0);
    const per=k=>{ const f=(settings.sauces[k].items||[]).find(x=>x.name===n); return f?(+f.use||0):0 };
    const q=s=>card.querySelector(s);
    q('.sp-in').textContent=kg1(e.g)+' كغم';
    q('.sp-used').textContent=kg1(e.used)+' كغم';
    q('.sp-val').textContent=fmt(Math.round(left*supPrice(n)))+' د.ع';
    q('.sp-left').textContent=neg?'0 كغم':kg1(left)+' كغم';
    const w=q('.fwarn'); w.hidden=!neg; w.textContent=neg?('انصرف '+kg1(e.used-e.g)+' كغم أكثر من المسواك. اكتب الموجود بالجرد.'):'';
    q('.sp-per').textContent='بكل سمجة: صلصة حمرة '+per('red')+' غ، صلصة سودة '+per('black')+' غ';
    const r=q('.sp-rice'); if(document.activeElement!==r) r.value=e.perRice||0;
  });
}
document.querySelectorAll('[data-sup]').forEach(card=>{
  const n=card.dataset.sup;
  card.querySelector('.sp-rice').addEventListener('change',ev=>{ const S=supAll(); S[n].perRice=Math.max(0,parseFloat(ev.target.value)||0); saveAll(); supRender() });
  card.querySelector('.sp-cbtn').addEventListener('click',()=>{ const S=supAll(), v=parseFloat(card.querySelector('.sp-c').value);
    if(!(v>=0)){ toast('اكتب الوزن بالكيلو'); return }
    S[n].g=Math.round(((S[n].used||0)+v*1000)*10)/10; card.querySelector('.sp-c').value=''; saveAll(); supRender(); toast('انحفظ: '+n+' '+v+' كغم') });
});
